//! Characters described in words. A script names a person and lists traits from a closed
//! vocabulary (`Sócrates (careca, barba longa branca, toga branca, pergaminho)`); the engine
//! draws those traits as a flat vector figure. The same description always gives the same
//! drawing, nothing is generated by an image model, and no likeness, logo or crest is ever
//! traced: identification comes from the name and the chosen traits.
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Skin {
    Light,
    Medium,
    Tan,
    Dark,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Hair {
    Bald,
    Short,
    Long,
    Curly,
    Bun,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum HairColour {
    Black,
    Brown,
    Blonde,
    Red,
    Grey,
    White,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Beard {
    None,
    Moustache,
    Goatee,
    Short,
    Long,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Outfit {
    Shirt,
    Suit,
    Toga,
    LabCoat,
    Hoodie,
    Dress,
    /// A plain sports jersey: colour and an optional number, never a club crest.
    Jersey,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Colour {
    Blue,
    Red,
    Green,
    Yellow,
    White,
    Black,
    Purple,
    Orange,
    Grey,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Prop {
    None,
    Scroll,
    Book,
    Ball,
    Whistle,
    Microphone,
    Laptop,
    Flask,
    Trophy,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Persona {
    /// Shown above the speech card so the audience knows who is talking.
    pub name: String,
    pub skin: Skin,
    pub hair: Hair,
    pub hair_colour: HairColour,
    pub beard: Beard,
    pub beard_colour: HairColour,
    pub outfit: Outfit,
    pub colour: Colour,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub number: Option<u8>,
    pub prop: Prop,
    #[serde(default)]
    pub glasses: bool,
    #[serde(default)]
    pub laurel: bool,
}

pub const MAX_NAME_CHARS: usize = 40;
pub const MAX_TRAITS: usize = 10;

/// Every trait word the parser understands, for error messages and the model's grammar.
pub const VOCABULARY: &str = "pele clara|media|morena|escura; careca ou cabelo curto|longo|cacheado|coque com cor preto|castanho|loiro|ruivo|grisalho|branco; bigode|cavanhaque|barba curta|barba longa (com cor); camisa|terno|toga|jaleco|moletom|vestido|uniforme (com cor azul|vermelho|verde|amarelo|branco|preto|roxo|laranja|cinza e numero 1-99); pergaminho|livro|bola|apito|microfone|notebook|frasco|trofeu; oculos; louros";

fn fold(text: &str) -> String {
    text.to_lowercase()
        .chars()
        .map(|c| match c {
            'á' | 'à' | 'â' | 'ã' => 'a',
            'é' | 'ê' => 'e',
            'í' => 'i',
            'ó' | 'ô' | 'õ' => 'o',
            'ú' | 'ü' => 'u',
            'ç' => 'c',
            other => other,
        })
        .collect()
}

fn hair_colour(word: &str) -> Option<HairColour> {
    Some(match word {
        "preto" | "preta" | "pretos" | "negro" => HairColour::Black,
        "castanho" | "castanha" | "castanhos" => HairColour::Brown,
        "loiro" | "loira" | "loiros" => HairColour::Blonde,
        "ruivo" | "ruiva" | "ruivos" => HairColour::Red,
        "grisalho" | "grisalha" | "grisalhos" | "cinza" => HairColour::Grey,
        "branco" | "branca" | "brancos" => HairColour::White,
        _ => return None,
    })
}

fn colour(word: &str) -> Option<Colour> {
    Some(match word {
        "azul" => Colour::Blue,
        "vermelho" | "vermelha" => Colour::Red,
        "verde" => Colour::Green,
        "amarelo" | "amarela" => Colour::Yellow,
        "branco" | "branca" => Colour::White,
        "preto" | "preta" => Colour::Black,
        "roxo" | "roxa" => Colour::Purple,
        "laranja" => Colour::Orange,
        "cinza" => Colour::Grey,
        _ => return None,
    })
}

fn outfit(word: &str) -> Option<Outfit> {
    Some(match word {
        "camisa" | "camiseta" => Outfit::Shirt,
        "terno" | "paleto" => Outfit::Suit,
        "toga" | "tunica" | "manto" => Outfit::Toga,
        "jaleco" => Outfit::LabCoat,
        "moletom" => Outfit::Hoodie,
        "vestido" => Outfit::Dress,
        "uniforme" => Outfit::Jersey,
        _ => return None,
    })
}

fn prop(trait_: &str) -> Option<Prop> {
    Some(match trait_ {
        "pergaminho" => Prop::Scroll,
        "livro" => Prop::Book,
        "bola" => Prop::Ball,
        "apito" => Prop::Whistle,
        "microfone" => Prop::Microphone,
        "notebook" | "laptop" => Prop::Laptop,
        "frasco" => Prop::Flask,
        "trofeu" | "taca" => Prop::Trophy,
        _ => return None,
    })
}

/// Parses `Nome (traço, traço, ...)`. Returns `Ok(None)` when there is no description, so a
/// bare name can be resolved against the script's cast. Unknown traits are an error: a
/// silently ignored word would draw someone the script did not describe.
pub fn parse(spec: &str) -> Result<Option<Persona>, String> {
    let spec = spec.trim();
    let Some(open) = spec.find('(') else {
        return Ok(None);
    };
    if !spec.ends_with(')') {
        return Err("feche a descrição do personagem com ')'".into());
    }
    let name = spec[..open].trim();
    if name.is_empty() || name.chars().count() > MAX_NAME_CHARS {
        return Err(format!(
            "o nome do personagem precisa de 1 a {MAX_NAME_CHARS} caracteres"
        ));
    }
    let traits: Vec<String> = spec[open + 1..spec.len() - 1]
        .split(',')
        .map(|item| fold(item.trim()))
        .filter(|item| !item.is_empty())
        .collect();
    if traits.is_empty() || traits.len() > MAX_TRAITS {
        return Err(format!(
            "descreva o personagem com 1 a {MAX_TRAITS} traços separados por vírgula"
        ));
    }
    let mut persona = Persona {
        name: name.to_string(),
        skin: Skin::Medium,
        hair: Hair::Short,
        hair_colour: HairColour::Black,
        beard: Beard::None,
        beard_colour: HairColour::Black,
        outfit: Outfit::Shirt,
        colour: Colour::Blue,
        number: None,
        prop: Prop::None,
        glasses: false,
        laurel: false,
    };
    let mut beard_colour = None;
    for trait_ in &traits {
        let words: Vec<&str> = trait_.split_whitespace().collect();
        let unknown = || format!("traço '{trait_}' não existe; use {VOCABULARY}");
        match words.as_slice() {
            ["pele", tone] => {
                persona.skin = match *tone {
                    "clara" | "branca" => Skin::Light,
                    "media" => Skin::Medium,
                    "morena" | "parda" => Skin::Tan,
                    "escura" | "negra" | "preta" => Skin::Dark,
                    _ => return Err(unknown()),
                }
            }
            ["careca"] | ["calvo"] => persona.hair = Hair::Bald,
            ["coque"] => persona.hair = Hair::Bun,
            ["cabelo", rest @ ..] if !rest.is_empty() => {
                for word in rest {
                    match *word {
                        "curto" => persona.hair = Hair::Short,
                        "longo" | "comprido" => persona.hair = Hair::Long,
                        "cacheado" | "crespo" | "encaracolado" | "black" => {
                            persona.hair = Hair::Curly
                        }
                        "em" | "de" => {}
                        "coque" => persona.hair = Hair::Bun,
                        other => persona.hair_colour = hair_colour(other).ok_or_else(unknown)?,
                    }
                }
            }
            [single] if hair_colour(single).is_some() && colour(single).is_none() => {
                persona.hair_colour = hair_colour(single).expect("checked");
            }
            ["bigode", rest @ ..] | ["cavanhaque", rest @ ..] | ["barba", rest @ ..] => {
                persona.beard = match words[0] {
                    "bigode" => Beard::Moustache,
                    "cavanhaque" => Beard::Goatee,
                    _ => Beard::Short,
                };
                for word in rest {
                    match *word {
                        "curta" | "rala" => persona.beard = Beard::Short,
                        "longa" | "comprida" | "cheia" => persona.beard = Beard::Long,
                        other => beard_colour = Some(hair_colour(other).ok_or_else(unknown)?),
                    }
                }
            }
            ["oculos"] => persona.glasses = true,
            ["louros"] | ["coroa", "de", "louros"] => persona.laurel = true,
            [first, rest @ ..] if outfit(first).is_some() => {
                persona.outfit = outfit(first).expect("checked");
                for word in rest {
                    if let Ok(number) = word.parse::<u8>() {
                        if !(1..=99).contains(&number) {
                            return Err("o número do uniforme vai de 1 a 99".into());
                        }
                        persona.number = Some(number);
                        // A shirt with a number is a sports jersey.
                        persona.outfit = Outfit::Jersey;
                    } else if !matches!(*word, "de" | "do" | "da" | "time" | "numero") {
                        persona.colour = colour(word).ok_or_else(unknown)?;
                    }
                }
            }
            _ => persona.prop = prop(trait_).ok_or_else(unknown)?,
        }
    }
    persona.beard_colour = beard_colour.unwrap_or(persona.hair_colour);
    Ok(Some(persona))
}

/// Key a script uses to refer back to a described character: the name, case and accents folded.
pub fn key(name: &str) -> String {
    fold(name.trim())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_philosopher_and_a_footballer_from_words() {
        let socrates = parse(
            "Sócrates (careca, barba longa branca, toga branca, pele clara, pergaminho, louros)",
        )
        .unwrap()
        .unwrap();
        assert_eq!(socrates.name, "Sócrates");
        assert_eq!(socrates.hair, Hair::Bald);
        assert_eq!(
            (socrates.beard, socrates.beard_colour),
            (Beard::Long, HairColour::White)
        );
        assert_eq!(
            (socrates.outfit, socrates.colour),
            (Outfit::Toga, Colour::White)
        );
        assert_eq!(
            (socrates.skin, socrates.prop, socrates.laurel),
            (Skin::Light, Prop::Scroll, true)
        );

        let striker =
            parse("Camisa 10 (pele escura, cabelo cacheado preto, camisa 10 amarela, bola)")
                .unwrap()
                .unwrap();
        assert_eq!(
            (striker.outfit, striker.number, striker.colour),
            (Outfit::Jersey, Some(10), Colour::Yellow)
        );
        assert_eq!(
            (striker.hair, striker.hair_colour),
            (Hair::Curly, HairColour::Black)
        );
        assert_eq!(
            striker.beard_colour,
            HairColour::Black,
            "beard follows the hair"
        );
    }

    #[test]
    fn bare_names_defer_to_the_cast_and_unknown_traits_are_refused() {
        assert_eq!(parse("Platão").unwrap(), None);
        let error = parse("Platão (sábio, toga)").unwrap_err();
        assert!(
            error.contains("'sabio'") && error.contains("pergaminho"),
            "{error}"
        );
        assert!(parse("Platão (toga").unwrap_err().contains("')'"));
        assert!(parse(" (toga)").unwrap_err().contains("nome"));
        assert!(parse("Juiz (uniforme 120 preto)")
            .unwrap_err()
            .contains("1 a 99"));
        assert_eq!(key("  Sócrates "), key("socrates"));
    }
}
